UPDATE sys_legal_doc
SET title = #{title}, content_md = #{contentMd}, status = #{status}, updated_by = #{updatedBy}
WHERE doc_type = #{docType}

UPDATE sys_legal_doc
SET status = 'PUBLISHED',
    published_at = COALESCE(published_at, NOW()),
    published_by = #{userId},
    updated_by = #{userId}
WHERE doc_type = #{docType}

UPDATE sys_legal_doc
SET published_at = COALESCE(published_at, NOW()),
    published_by = #{userId}
WHERE doc_type = #{docType}
